export const DEFAULT_ATTACKER_EMBLEM: AttackerEmblemId = "crow";
export const ATTACKER_EMBLEM_KEY = "brandubh.attackerEmblem";

const IDS = new Set<string>(ATTACKER_EMBLEMS.map((e) => e.id));
export function isAttackerEmblemId(v: unknown): v is AttackerEmblemId {
  return typeof v === "string" && IDS.has(v);
}
export function emblemById(id: AttackerEmblemId): EmblemDef {
  return ATTACKER_EMBLEMS.find((e) => e.id === id) ?? ATTACKER_EMBLEMS[0];
}
/** Centre of an emblem's viewBox — used to place the optional circular rim. */
export function emblemCenter(viewBox: string): { cx: number; cy: number } {
  const [x, y, w, h] = viewBox.split(/\s+/).map(Number);
  return { cx: x + w / 2, cy: y + h / 2 };
}
export function loadAttackerEmblem(): AttackerEmblemId {
  try {
    const s = localStorage.getItem(ATTACKER_EMBLEM_KEY);
    if (isAttackerEmblemId(s)) return s;
  } catch {
    /* ignore */
  }
  return DEFAULT_ATTACKER_EMBLEM;
}
